if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ae5ae8ad7f4f0009e8143b42' and md5(to_jsonb(t)::text)='c1fd907325b6284a947373c6cd642661')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:ae5ae8ad7f4f0009e8143b42';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_4e43ab3be2a23132${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:ae5ae8ad7f4f0009e8143b42","revision":2,"language":"es","name":"Herramientas de ladrón","aliases":["Herramientas de los ladrones"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:4d03975db485caf5a0345f4088b25f09eb95685f33c71afe598aeb1214eb0623","kind":"legacy","title":"Herramientas de los ladrones","language":"es","rulesEdition":null,"locator":"official:equipment:es:ae5ae8ad7f4f0009e8143b42","verified":false},{"id":"original:b00c62ecb3067e64c45af2950a32d040572bc87536a10216449a3a6582abbf8e","kind":"legacy","title":"Herramientas de ladrón","language":"es","rulesEdition":null,"locator":"official:equipment:es:ae5ae8ad7f4f0009e8143b42","verified":false},{"id":"original:9888ef57b8ea084f0676173f2b304b3a15e51cfb6abb5e7b5f7f15719c4907b3","kind":"legacy","title":"Thieves' Tools","language":"en","rulesEdition":null,"locator":"official:equipment:eng:7fcbd42d594c48df8ccf79ef","verified":false},{"id":"original:13d0eddf8869fe0183cc696449fd17d9dd0ff713820f23872e1a526ba3a7900e","kind":"legacy","title":"Thieves' Tools","language":"en","rulesEdition":null,"locator":"official:equipment:eng:7fcbd42d594c48df8ccf79ef","verified":false},{"id":"srd-5.1-en-equipment","kind":"srd","title":"SRD 5.1 · original inglés","language":"en","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf · página PDF 70 · CC BY 4.0","verified":true},{"id":"srd-5.1-es-equipment","kind":"srd","title":"SRD 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 73 · CC BY 4.0","verified":true},{"id":"srd-5.1-es-tools-context","kind":"srd","title":"SRD 5.1 · herramientas, instrumentos y juegos · español oficial","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · páginas PDF 72–73 · CC BY 4.0","verified":true}],"category":"tool","subtypes":[],"magical":false,"rarity":"none","consumable":false,"properties":[],"weight":{"value":1,"unit":"lb"},"economy":{"basePrice":{"quantity":25,"unit":"gp"},"campaignPrice":null,"explanation":"Precio cotejado con la tabla oficial de 2014. Los precios de las copias de personajes y comerciantes se conservan."},"description":[{"id":"official-table-row","section":"description","provenance":"reviewed-translation","sourceIds":["srd-5.1-en-equipment"],"type":"table","columns":["Objeto","Precio","Peso"],"rows":[["Herramientas de ladrón","25 po","1 lb."]]},{"id":"official-prose","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Herramientas de ladrón. Este conjunto de herramientas incluye una lima pequeña, un juego de ganzúas, un espejito con un asa metálica, una serie de tijeras de punta estrecha y unas tenazas. Si tienes competencia con estas herramientas, podrás sumar tu bonificador por competencia a las pruebas de característica para desarmar trampas o forzar cerraduras."},{"id":"tools-context-general","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"mundane-rule","name":"Uso del equipo","activation":"other","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"target":"Según las reglas del objeto.","range":"","duration":"Según la regla.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"tool-check","kind":"tool-check","toolKey":"thieves-tools","condition":""}],"execution":{"mode":"automatic","handler":"equipment-tool-check","explanation":"Prueba de herramienta con característica elegida, competencia, pericia y Talento Seguro cuando corresponden.","pendingAutomation":[]},"textBlockIds":["official-prose"]}],"recoverySourceIds":["4d03975db485caf5a0345f4088b25f09eb95685f33c71afe598aeb1214eb0623","b00c62ecb3067e64c45af2950a32d040572bc87536a10216449a3a6582abbf8e","9888ef57b8ea084f0676173f2b304b3a15e51cfb6abb5e7b5f7f15719c4907b3","13d0eddf8869fe0183cc696449fd17d9dd0ff713820f23872e1a526ba3a7900e"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Conservar los originales y cerrar la recuperación de información antes de eliminar versiones.","El uso particular continúa siendo asistido y está explicado en el objeto."]}}$native_4e43ab3be2a23132$::jsonb,true),'{features}',$native_5c3ba9d5bc2ed536$[{"id":"mundane-rule","kind":"other","name":"Uso del equipo","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de ladrón. Este conjunto de herramientas incluye una lima pequeña, un juego de ganzúas, un espejito con un asa metálica, una serie de tijeras de punta estrecha y unas tenazas. Si tienes competencia con estas herramientas, podrás sumar tu bonificador por competencia a las pruebas de característica para desarmar trampas o forzar cerraduras.\n\nResolver las reglas descritas y sus condiciones en la mesa.\n\nDuración: Según la regla..","showInActions":false}]$native_5c3ba9d5bc2ed536$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ae5ae8ad7f4f0009e8143b42';
